import{_ as e,b as o,c as a,I as s}from"./chunks/framework.C6cPs9Ia.js";const q=JSON.parse('{"title":"QQ飞车：漂移过弯的十六岁","description":"一个高中生的 QQ 飞车生涯记录——段位沉浮、漂移心得与开黑日常","frontmatter":{"title":"QQ飞车：漂移过弯的十六岁","date":"2026-09-16T00:00:00.000Z","tags":["QQ飞车","游戏","日常"],"cover":"/LQY/images/cover-qqspeed.webp","head":[["meta",{"name":"description","content":"一个高中生的 QQ 飞车生涯记录——段位沉浮、漂移心得与开黑日常"}],["meta",{"name":"keywords","content":"QQ飞车, 赛车游戏, 段位, 漂移, 游戏"}]]},"headers":[],"relativePath":"posts/qq-speed.md","filePath":"posts/qq-speed.md"}'),r={name:"posts/qq-speed.md"};function l(i,t,n,p,d,c){return o(),a("div",null,[...t[0]||(t[0]=[s('<p>如果说猫羽雫是我的精神支柱，那 QQ 飞车就是我的肾上腺素来源。</p><p><strong>左手方向，右手氮气，十六岁的心跳和引擎声一个频率。</strong></p><hr><h2 id="入坑简史" tabindex="-1">入坑简史 <a class="header-anchor" href="#入坑简史" aria-label="Permalink to &quot;入坑简史&quot;">​</a></h2><p>最早是在亲戚家电脑上玩到的 QQ 飞车端游——那时候我连漂移是什么都不知道，全程撞墙，撞出了感情。后来自己有了手机，转战手游，才算真正入坑。</p><p>现在的情况：</p><ul><li><strong>段位</strong>：在钻石和星耀之间反复横跳（上去就浪，浪完就掉，人生循环）</li><li><strong>本命车</strong>：A 车里挑了辆蓝色涂装的——没办法，本命是蓝发的，车也得是蓝的，这叫配套</li><li><strong>常用地图</strong>：十一城（窄弯多，漂移爽）、滨海沙滩（新手村记忆）、西部矿山（卡bug练图）</li></ul><h2 id="漂移这件事-手感比理论重要" tabindex="-1">漂移这件事，手感比理论重要 <a class="header-anchor" href="#漂移这件事-手感比理论重要" aria-label="Permalink to &quot;漂移这件事，手感比理论重要&quot;">​</a></h2><p>新手期看了无数教学视频，什么&quot;最佳漂移角度&quot;&quot;双喷衔接&quot;，看完感觉会了，上手依然撞墙。</p><p>后来才悟了：<strong>漂移是肌肉记忆，不是数学题。</strong>（虽然我数学也不咋地，这可能是同一个问题。）</p><p>给还在练习的萌新三条血泪经验：</p><ol><li><strong>别贪氮气</strong>。弯道攒的氮气留着出弯用，弯中喷等于自杀。</li><li><strong>提前半个车身入弯</strong>。你以为的最佳路线其实已经晚了。</li><li><strong>失误了别松手</strong>。小擦墙靠拉方向能救回来，一松手就真撞死了。</li></ol><h2 id="高中生的开黑日常" tabindex="-1">高中生的开黑日常 <a class="header-anchor" href="#高中生的开黑日常" aria-label="Permalink to &quot;高中生的开黑日常&quot;">​</a></h2><p>周五晚上是固定开黑时间。三个同学，语音里一半在报弯道，一半在哀嚎月考。</p><p>最离谱的一次：领跑的哥们最后一个弯道浪过头撞墙，被我们仨连环超越，赛后语音里安静得像默剧，然后他幽幽来了一句：&quot;我这是给你们让路，圣诞节快到了。&quot;</p><p>好家伙，我们打的是慈善赛是吧。</p><div class="tip custom-block"><p class="custom-block-title">高中生电竞守则</p><ul><li>周内不玩，周五放肆（这样家长查岗的时候理直气壮）</li><li>输了不摔手机——摔了就没得玩了，这是经济学</li><li>段位可以掉，礼貌不能掉，开局&quot;GL&quot;，结束&quot;GG&quot;</li></ul></div><h2 id="为什么留恋这个游戏" tabindex="-1">为什么留恋这个游戏 <a class="header-anchor" href="#为什么留恋这个游戏" aria-label="Permalink to &quot;为什么留恋这个游戏&quot;">​</a></h2><p>说到底，QQ 飞车教会我的不只是漂移。</p><p>它让我知道：<strong>过弯要减速，但人生的直道要敢踩油门。</strong>（好像有点中二，但十六岁嘛，中二是标配。）</p><p>哪天在赛道上遇到一辆开得又稳又慢的蓝色小车，说不定就是我——在练新图，顺便等谁发个好友申请。</p><p>GG，下把见。</p>',22)])])}const h=e(r,[["render",l]]);export{q as __pageData,h as default};
